def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The colored key indicates the relative amounts of each color. Transfer
    # those proportions onto the 2x2 tiles making up the 8-shaped figure.
    counts = {}
    for row in grid:
        for v in row:
            if v not in (0, 8):
                counts[v] = counts.get(v, 0) + 1
    if not counts:
        return out

    tiles = []
    for r in range(0, h, 2):
        for c in range(0, w, 2):
            cells = [(y, x) for y in range(r, min(r + 2, h))
                     for x in range(c, min(c + 2, w)) if grid[y][x] == 8]
            if cells:
                tiles.append(cells)

    colors = list(counts)
    total_key = sum(counts.values())
    total_tiles = len(tiles)
    assignment = []
    for color in colors:
        assignment.extend([color] * round(total_tiles * counts[color] / total_key))
    assignment = (assignment + [colors[-1]] * total_tiles)[:total_tiles]

    for cells, color in zip(tiles, assignment):
        for r, c in cells:
            out[r][c] = color
    return out
