def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # The small colored arrangement is the key for coloring the three
    # horizontal sections of the large 8-shape.
    key = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
           if grid[r][c] not in (0, 8)]
    if not key:
        return out

    # Use the key's top, middle, and bottom marker colors in the same order
    # as the upper, connecting, and lower parts of the large figure.
    by_row = sorted(key)
    ordered_colors = []
    for _, _, color in by_row:
        if color not in ordered_colors:
            ordered_colors.append(color)

    rows = [r for r in range(h) if 8 in grid[r]]
    if not rows:
        return out
    lo, hi = min(rows), max(rows)
    for r in rows:
        if r <= lo + (hi - lo) // 3:
            color = ordered_colors[0]
        elif r <= lo + 2 * (hi - lo) // 3:
            color = ordered_colors[1 % len(ordered_colors)]
        else:
            color = ordered_colors[2 % len(ordered_colors)]
        for c in range(w):
            if grid[r][c] == 8:
                out[r][c] = color
    return out
